  "ground_truth" TEXT,
  "expected_decision" TEXT
);
CREATE TABLE "holdings" (
"holding_id" TEXT,
  "portfolio_id" TEXT,
  "instrument_id" TEXT,
  "quantity" REAL,
  "cost_basis" REAL,
  "as_of_date" TEXT,
  "status" TEXT
);
CREATE TABLE "instruments" (
"instrument_id" TEXT,
  "symbol" TEXT,
  "instrument_name" TEXT,
  "asset_class" TEXT,
  "currency" TEXT,
  "is_excluded" INTEGER,
  "liquidity_tier" TEXT,
  "active" INTEGER
);
CREATE TABLE "investor_profiles" (
"investor_id" TEXT,
  "risk_profile" TEXT,
  "base_currency" TEXT,
  "created_date" TEXT
);
CREATE TABLE "market_prices" (
"price_id" TEXT,
  "instrument_id" TEXT,
  "price_date" TEXT,
  "close_price" REAL,
  "currency" TEXT,
  "source" TEXT
);
CREATE TABLE "portfolios" (
"portfolio_id" TEXT,
